using Payments;

namespace PaymentGateway.Tests;

[TestClass]
public sealed class PaymentGatewayTests
{
    private readonly FakePaymentProcessor _processor;
    private readonly Payments.PaymentGateway _gateway;

    public PaymentGatewayTests()
    {
        _processor = new FakePaymentProcessor();
        _gateway = new Payments.PaymentGateway(_processor);
    }

    #region Constructor

    [TestMethod]
    public void Constructor_NullProcessor_ThrowsArgumentNullException()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(() => new Payments.PaymentGateway(null!));
        Assert.AreEqual("processor", ex.ParamName);
    }

    #endregion

    #region ChargeAsync

    [TestMethod]
    public async Task ChargeAsync_ValidInput_ReturnsSuccessfulCharge()
    {
        _processor.NextChargeId = "ch_12345";

        var result = await _gateway.ChargeAsync("tok_visa", 49.99m);

        Assert.AreEqual("ch_12345", result.ChargeId);
        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_ProcessorReturnsEmpty_ReturnsFailedCharge()
    {
        _processor.NextChargeId = "";

        var result = await _gateway.ChargeAsync("tok_visa", 10m);

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public async Task ChargeAsync_InvalidCardToken_ThrowsArgumentException(string? token)
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync(token!, 10m));
        Assert.AreEqual("cardToken", ex.ParamName);
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    [DataRow(-100.50)]
    public async Task ChargeAsync_InvalidAmount_ThrowsArgumentOutOfRangeException(double amount)
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_visa", (decimal)amount));
        Assert.AreEqual("amount", ex.ParamName);
    }

    [TestMethod]
    [DataRow(0.01)]
    [DataRow(1.00)]
    [DataRow(9999.99)]
    public async Task ChargeAsync_VariousValidAmounts_Succeeds(double amount)
    {
        _processor.NextChargeId = "ch_ok";

        var result = await _gateway.ChargeAsync("tok_visa", (decimal)amount);

        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_PassesCorrectParametersToProcessor()
    {
        _processor.NextChargeId = "ch_abc";

        await _gateway.ChargeAsync("tok_mastercard", 75.00m);

        Assert.AreEqual("tok_mastercard", _processor.LastChargeToken);
        Assert.AreEqual(75.00m, _processor.LastChargeAmount);
    }

    #endregion

    #region RefundAsync

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccessfulRefund()
    {
        _processor.NextRefundId = "re_67890";

        var result = await _gateway.RefundAsync("ch_12345");

        Assert.AreEqual("re_67890", result.RefundId);
        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task RefundAsync_ProcessorReturnsEmpty_ReturnsFailedRefund()
    {
        _processor.NextRefundId = "";

        var result = await _gateway.RefundAsync("ch_12345");

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public async Task RefundAsync_InvalidChargeId_ThrowsArgumentException(string? chargeId)
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(chargeId!));
        Assert.AreEqual("chargeId", ex.ParamName);
    }

    [TestMethod]
    public async Task RefundAsync_PassesCorrectChargeIdToProcessor()
    {
        _processor.NextRefundId = "re_xyz";

        await _gateway.RefundAsync("ch_target");

        Assert.AreEqual("ch_target", _processor.LastRefundChargeId);
    }

    #endregion

    #region ProcessWebhook

    [TestMethod]
    [DataRow("charge.succeeded", "Charge confirmed")]
    [DataRow("charge.failed", "Charge failed")]
    [DataRow("refund.created", "Refund initiated")]
    public void ProcessWebhook_KnownEvent_ReturnsProcessed(string eventType, string expectedMessage)
    {
        var result = _gateway.ProcessWebhook(eventType, "{\"id\":\"evt_1\"}");

        Assert.AreEqual(WebhookStatus.Processed, result.Status);
        Assert.AreEqual(expectedMessage, result.Message);
